import java.io.*;
import java.util.*;

public class Main {
    private static long count(long x) {
        if (x <= 0) return 0;

        long result = 0;
        for (int length = 2; length <= 60; length++) {
            long allOnes = (1L << length) - 1;
            for (int zeroPosition = 0; zeroPosition < length - 1; zeroPosition++) {
                long value = allOnes - (1L << zeroPosition);
                if (value <= x) result++;
            }
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long b = scanner.nextLong();

        System.out.println(count(b) - count(a - 1));
    }
}

