import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long a = fs.nextLong();
        long b = fs.nextLong();

        System.out.println(count(b) - count(a - 1));
    }

    private static long count(long limit) {
        if (limit < 2) return 0;

        long result = 0;
        for (int length = 2; length <= 60; length++) {
            long allOnes = (1L << length) - 1;

            for (int zeroPosition = 0; zeroPosition < length - 1; zeroPosition++) {
                long value = allOnes ^ (1L << zeroPosition);
                if (value <= limit) result++;
            }
        }
        return result;
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}

